<?php
defined('ABSPATH') || exit;
function cdra_discovery_authorize($nonce,$action){cdra_need(cdra_staging()&&current_user_can('manage_options'),'discovery_forbidden');cdra_need(is_string($nonce)&&wp_verify_nonce($nonce,$action),'discovery_nonce');}
function cdra_discovery_admin_hooks(){
 add_action('admin_menu',static function(){add_submenu_page('cyberdat-research','Source Registry','Source Registry','manage_options','cyberdat-sources','cdra_discovery_registry_page');});
 add_action('admin_post_cdra_discovery',static function(){try{
  $data=wp_unslash($_POST);cdra_discovery_authorize($data['_wpnonce']??'','cdra_discovery');$s=new CDRA_Store();$ds=new CDRA_Discovery_Store($s);$action=$data['operation']??'';
  if($action==='source'){$source=$data['source']??'';$r=cdra_discovery_registry()[$source]??null;cdra_need($r&&$r['connection']!=='BLOCKED'&&in_array($data['enabled']??'', ['0','1'],true),'source_blocked');$enabled=$data['enabled']==='1';$before=$s->get('discovery_enabled:'.$source,false);$s->transaction(function()use($s,$ds,$source,$before,$enabled){$s->put('discovery_enabled:'.$source,$enabled);$ds->audit('source_toggle',0,[$source=>$before],[$source=>$enabled],get_current_user_id());});}
  elseif(in_array($action,['merge','split'],true)){$raw=$data['ids']??'';cdra_need(is_string($raw)&&preg_match('/^[1-9]\d{0,9}(?:,[1-9]\d{0,9}){0,24}$/D',$raw),'group_ids');$ds->regroup(array_map('intval',explode(',',$raw)),$action==='split',get_current_user_id());}
  elseif($action==='classify'){$id=$data['item_id']??'';$categories=$data['categories']??[];$hash=$data['content_hash']??'';cdra_need(is_string($id)&&ctype_digit($id)&&(int)$id>0&&is_array($categories)&&count($categories)<=count(cdra_discovery_categories())&&is_string($hash)&&preg_match('/^[a-f0-9]{64}$/D',$hash),'classification_input');$ds->correct((int)$id,$categories,get_current_user_id(),$hash);}
  else{throw new CDRA_Error('invalid_action');}
  wp_safe_redirect(admin_url('admin.php?page='.($action==='source'?'cyberdat-sources':'cyberdat-research').'&updated=1'));exit;
 }catch(Throwable $e){wp_die('Research action rejected; reload current evidence.','Research',['response'=>400]);}});
}
function cdra_discovery_registry_page(){
 cdra_need(cdra_staging()&&current_user_can('manage_options'),'registry_forbidden');$s=new CDRA_Store();echo '<div class="wrap"><h1>Source Registry</h1><p>Enabled is permission to poll, not proof of ACTIVE ingestion. ACTIVE requires fetch, parse and committed records. No article publication.</p><table class="widefat striped"><thead><tr><th>Publisher / source</th><th>Acquisition / interval</th><th>Health / counts</th><th>Control</th></tr></thead><tbody>';
 $all=cdra_sources()+cdra_discovery_registry();foreach($all as $id=>$r){$h=$s->get('health:'.$id,[]);$legacy=isset(cdra_sources()[$id]);$enabled=$legacy||cdra_discovery_enabled($id,$s);$status=($r['connection']??'')==='BLOCKED'?'Blocked':(!$enabled?'Disabled':(!empty($h['last_error'])?'Error':(!empty($h['last_success'])&&time()-$h['last_success']<=($r['fresh']??$r['interval']*3)?'Fresh':'Stale')));
  echo '<tr><td>'.esc_html(($r['publisher']??$r['name']).' / '.$r['name']).'<br>'.esc_html($r['stream']??'Vulnerability intelligence').'<br><a href="'.esc_url($r['website']??$r['url']).'" rel="noopener noreferrer">Official source</a></td><td>'.esc_html(($r['format']??'Unverified').' · '.($r['interval']/3600).' hours').'<br>'.esc_html($r['url']??'No permitted endpoint verified').'</td><td>'.esc_html($status.' · '.($h['connection']??($legacy&&!empty($h['last_success'])?'ACTIVE':'Not proven ACTIVE'))).'<br>'.esc_html('Attempt: '.(!empty($h['last_attempt'])?gmdate('c',$h['last_attempt']):'Never').' · Success: '.(!empty($h['last_success'])?gmdate('c',$h['last_success']):'Never')).'<br>'.esc_html('Discovered '.($h['records_discovered_total']??0).' / inserted '.($h['records_inserted_total']??0).' / duplicates '.($h['records_duplicates_total']??0)).'<br>'.esc_html('Error: '.($h['last_error']??'').' · '.($r['reason']??'')).'</td><td>';
  if(!$legacy&&($r['connection']??'')!=='BLOCKED'){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="cdra_discovery"><input type="hidden" name="operation" value="source"><input type="hidden" name="source" value="'.esc_attr($id).'"><input type="hidden" name="enabled" value="'.($enabled?'0':'1').'">';wp_nonce_field('cdra_discovery');echo '<button class="button">'.($enabled?'Disable':'Enable').'</button></form>';}elseif($legacy){echo 'Existing collector retained';}else{echo 'Blocked: endpoint/access verification required';}echo '</td></tr>';
 }echo '</tbody></table></div>';
}
function cdra_discovery_queue_query($f){
 $s=new CDRA_Store();$p=$s->prefix;$where=['i.active=1'];$args=[];
 foreach(['source','status','stream','category'] as $key){$v=$f[$key]??'';if($v===''){continue;}$allowed=match($key){'source'=>array_keys(cdra_sources()+cdra_discovery_registry()),'status'=>array_keys(cdra_statuses()),'stream'=>['news','research','papers'],'category'=>cdra_discovery_categories()};cdra_need(is_string($v)&&in_array($v,$allowed,true),'invalid_filter');
  $where[]=match($key){'source'=>'i.source=%s','status'=>'i.editorial_status=%s','stream'=>'d.stream=%s','category'=>"EXISTS (SELECT 1 FROM {$p}categories c WHERE c.item_id=i.id AND c.category=%s)"};$args[]=$v;
 }
 if(($f['priority']??'')!==''){cdra_need(in_array($f['priority'],['High','Medium','Low'],true),'invalid_priority_filter');$score='COALESCE(i.manual_priority,i.priority)';$where[]=match($f['priority']){'High'=>"$score>=80",'Medium'=>"$score BETWEEN 50 AND 79",'Low'=>"$score<50"};}
 if(($f['date']??'')!==''){$date=$f['date'];cdra_need(is_string($date)&&preg_match('/^\d{4}-\d{2}-\d{2}$/D',$date)&&gmdate('Y-m-d',strtotime($date.' UTC'))===$date,'invalid_date');$where[]='i.published>=%s';$args[]=$date.' 00:00:00';}
 if(($f['q']??'')!==''){cdra_need(is_string($f['q'])&&mb_strlen($f['q'])<=160,'invalid_search');$q=$s->db->esc_like($f['q']);$where[]="(i.source_id LIKE %s OR JSON_UNQUOTE(JSON_EXTRACT(i.payload,'$.original_title')) LIKE %s OR EXISTS (SELECT 1 FROM {$p}cves c WHERE c.item_id=i.id AND c.cve LIKE %s) OR JSON_UNQUOTE(JSON_EXTRACT(d.metadata,'$.paper.doi')) LIKE %s OR JSON_UNQUOTE(JSON_EXTRACT(d.metadata,'$.paper.arxiv_id')) LIKE %s)";array_push($args,...array_fill(0,5,'%'.$q.'%'));}
 $base=" FROM {$p}items i LEFT JOIN {$p}discovery d ON d.item_id=i.id WHERE ".implode(' AND ',$where);$prepared=$args?$s->db->prepare($base,...$args):$base;
 $total=(int)$s->db->get_var('SELECT COUNT(*)'.$prepared);$page=max(1,min(480,(int)($f['paged']??1)));$rows=$s->db->get_results('SELECT i.*,d.topic_id,d.metadata,d.stream'.$prepared.' ORDER BY COALESCE(i.manual_priority,i.priority) DESC,i.published DESC,i.id DESC'.$s->db->prepare(' LIMIT 25 OFFSET %d',($page-1)*25),ARRAY_A);cdra_need(!$s->db->last_error,'queue_read');return ['rows'=>$rows,'total'=>$total,'page'=>$page];
}
function cdra_discovery_queue_page(){
 cdra_need(cdra_staging()&&current_user_can('manage_options'),'queue_forbidden');$f=[];foreach(['source','status','stream','category','priority','date','q','paged'] as $k){$v=wp_unslash($_GET[$k]??'');cdra_need(is_string($v),'invalid_filter');$f[$k]=sanitize_text_field($v);}$result=cdra_discovery_queue_query($f);
 echo '<div class="wrap"><h1>Research Queue</h1><p>News · Threat Intelligence &amp; Technical Research · Cybersecurity Research Papers. Ready for Content Agent is an editorial status only; no generation or publication occurs.</p><p><a href="'.esc_url(admin_url('admin.php?page=cyberdat-sources')).'">Source Registry and health</a></p><form method="get"><input type="hidden" name="page" value="cyberdat-research">';
 foreach(['stream'=>['news'=>'Cybersecurity News','research'=>'Threat Intelligence & Technical Research','papers'=>'Cybersecurity Research Papers'],'source'=>array_map(static fn($r)=>$r['name'],cdra_sources()+cdra_discovery_registry()),'status'=>cdra_statuses(),'category'=>array_combine(cdra_discovery_categories(),cdra_discovery_categories()),'priority'=>['High'=>'High','Medium'=>'Medium','Low'=>'Low']] as $k=>$options){echo '<label>'.esc_html(ucfirst($k)).' <select name="'.esc_attr($k).'"><option value="">All</option>';foreach($options as $value=>$label){echo '<option value="'.esc_attr($value).'" '.selected($f[$k],$value,false).'>'.esc_html($label).'</option>';}echo '</select></label> ';}
 echo '<label>Published since <input type="date" name="date" value="'.esc_attr($f['date']).'"></label> <label>Title / CVE / DOI / arXiv <input name="q" maxlength="160" value="'.esc_attr($f['q']).'"></label><button class="button">Filter</button></form><p>'.esc_html($result['total'].' matching records').'</p><table class="widefat striped"><thead><tr><th>Evidence / paper metadata</th><th>Priority / topic</th><th>Editorial workflow</th></tr></thead><tbody>';
 foreach($result['rows'] as $row){$r=json_decode($row['payload'],true);$meta=$row['metadata']?json_decode($row['metadata'],true):[];$reasons=json_decode($row['reasons'],true);echo '<tr><td><strong>#'.esc_html($row['id']).'</strong> <a href="'.esc_url($r['canonical_url']).'" target="_blank" rel="noopener noreferrer">'.esc_html($r['original_title']).'</a><p>'.esc_html($r['source_name'].' · Published '.$r['published'].' · Source updated '.$r['source_updated'].' · Discovered '.$row['first_seen']).'</p><p>'.esc_html($r['summary']).'</p><p>'.esc_html(implode(', ',$r['cve_ids'])).'</p>';
  if(!empty($meta['paper'])){echo '<details><summary>Scientific metadata</summary>';foreach($meta['paper'] as $key=>$value){echo '<p>'.esc_html($key.': '.(is_scalar($value)?(string)$value:(is_array($value)?implode(', ',$value):'Unknown'))).'</p>';}echo '<p>'.esc_html('Authors: '.implode('; ',$meta['authors']??[])).'</p></details>';}
  echo '</td><td>'.esc_html(($row['manual_priority']??$row['priority']).' / 100 · '.($row['manual_priority']!==null?'manual':'heuristic')).'<p>'.esc_html('Topic: '.($row['topic_id']??'Legacy evidence')).'</p><ul>';foreach($reasons['reasons']??[] as $reason){echo '<li>'.esc_html($reason['points'].' · '.$reason['explanation']).'</li>';}echo '</ul></td><td><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="cdra_save"><input type="hidden" name="item_id" value="'.esc_attr($row['id']).'"><input type="hidden" name="content_hash" value="'.esc_attr($row['content_hash']).'">';wp_nonce_field('cdra_item_'.$row['id']);echo '<label>Status <select name="status">';foreach(cdra_statuses() as $k=>$label){echo '<option value="'.esc_attr($k).'" '.selected($row['editorial_status'],$k,false).'>'.esc_html($label).'</option>';}echo '</select></label><label> Priority <input name="priority" type="number" min="0" max="100" value="'.esc_attr($row['manual_priority']??'').'"></label><button class="button">Save review</button></form>';
  if($row['metadata']){echo '<details><summary>Correct classification</summary><ul>';foreach($meta['classification_reasons']??[] as $reason){echo '<li>'.esc_html($reason['category'].': '.$reason['basis']).'</li>';}echo '</ul><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="cdra_discovery"><input type="hidden" name="operation" value="classify"><input type="hidden" name="item_id" value="'.esc_attr($row['id']).'"><input type="hidden" name="content_hash" value="'.esc_attr($row['content_hash']).'">';wp_nonce_field('cdra_discovery');foreach(cdra_discovery_categories() as $cat){echo '<label><input type="checkbox" name="categories[]" value="'.esc_attr($cat).'" '.checked(in_array($cat,$meta['manual_categories']??$r['categories']??[],true),true,false).'>'.esc_html($cat).'</label><br>';}echo '<button class="button">Save classification</button></form></details>';}
  echo '</td></tr>';
 }echo '</tbody></table>';foreach(['Previous'=>max(1,$result['page']-1),'Next'=>$result['page']+1] as $label=>$page){if($page<=max(1,ceil($result['total']/25))){echo '<a class="button" href="'.esc_url(add_query_arg(array_merge($f,['page'=>'cyberdat-research','paged'=>$page]),admin_url('admin.php'))).'">'.esc_html($label).'</a> ';}}
 echo '<h2>Manual event merge / split</h2><p>Explicit record IDs; source publications are preserved. Shared CVE alone never proves one event.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="cdra_discovery">';wp_nonce_field('cdra_discovery');echo '<label>Record IDs <input name="ids" placeholder="123,456" required></label><select name="operation"><option value="merge">Merge selected into one topic</option><option value="split">Split selected into separate topics</option></select><button class="button">Apply grouping</button></form></div>';
}
